import { createServer, IncomingMessage, ServerResponse } from 'http';
import { createHmac, timingSafeEqual } from 'crypto';
import { Buffer } from 'buffer';

const SERVICE_SECRET = process.env.SERVICE_SECRET || 'default-dev-secret';
const BUFFER_POOL: Map<string, { data: Buffer; refCount: number; released: boolean }> = new Map();

interface ProcessingContext {
  requestId: string;
  bufferKey: string;
  authenticated: boolean;
  stage: 'init' | 'processing' | 'complete' | 'error';
}

function verifyServiceToken(token: string, timestamp: string): boolean {
  const expected = createHmac('sha256', SERVICE_SECRET)
    .update(`${timestamp}:file-processor`)
    .digest();
  const provided = Buffer.from(token, 'hex');
  if (provided.length !== expected.length) return false;
  return timingSafeEqual(expected, provided);
}

function allocateBuffer(key: string, size: number): Buffer {
  const data = Buffer.alloc(size);
  BUFFER_POOL.set(key, { data, refCount: 1, released: false });
  return data;
}

function retainBuffer(key: string): Buffer | null {
  const entry = BUFFER_POOL.get(key);
  if (!entry || entry.released) return null;
  entry.refCount++;
  return entry.data;
}

function releaseBuffer(key: string): void {
  const entry = BUFFER_POOL.get(key);
  if (!entry) return;
  entry.refCount--;
  if (entry.refCount <= 0) {
    entry.released = true;
    entry.data.fill(0);
    BUFFER_POOL.delete(key);
  }
}

async function processFileChunk(ctx: ProcessingContext, chunk: Buffer): Promise<Buffer> {
  const poolBuf = retainBuffer(ctx.bufferKey);
  if (!poolBuf) {
    throw new Error('Buffer no longer available');
  }
  try {
    chunk.copy(poolBuf, 0, 0, Math.min(chunk.length, poolBuf.length));
    ctx.stage = 'processing';
    // Simulate async processing pipeline
    await new Promise(resolve => setTimeout(resolve, 10));
    return poolBuf;
  } finally {
    releaseBuffer(ctx.bufferKey);
  }
}

async function handleFileUpload(ctx: ProcessingContext, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) {
    chunks.push(chunk as Buffer);
  }
  const body = Buffer.concat(chunks);

  const buf = allocateBuffer(ctx.bufferKey, 4096);
  ctx.stage = 'processing';

  try {
    const result = await processFileChunk(ctx, body);
    // After processFileChunk, refCount was decremented in its finally block.
    // Now we attempt to do a "finalization" step that also releases.
    await finalizeProcessing(ctx, result);
    ctx.stage = 'complete';
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'processed', requestId: ctx.requestId }));
  } catch (err: any) {
    ctx.stage = 'error';
    // Error path also releases the buffer for cleanup
    releaseBuffer(ctx.bufferKey);
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.message }));
  }
}

async function finalizeProcessing(ctx: ProcessingContext, data: Buffer): Promise<void> {
  // Finalization: write audit log, then release the buffer
  await new Promise(resolve => setTimeout(resolve, 5));
  // This release corresponds to the initial allocateBuffer's refCount
  releaseBuffer(ctx.bufferKey);
}

function generateRequestId(): string {
  return `req-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
  const url = new URL(req.url || '/', `http://${req.headers.host}`);

  if (url.pathname !== '/api/process' || req.method !== 'POST') {
    res.writeHead(404);
    res.end('Not Found');
    return;
  }

  const authHeader = req.headers['x-service-auth'] as string;
  const timestampHeader = req.headers['x-service-timestamp'] as string;

  if (!authHeader || !timestampHeader) {
    res.writeHead(401);
    res.end('Unauthorized');
    return;
  }

  const now = Date.now();
  const requestTime = parseInt(timestampHeader, 10);
  if (isNaN(requestTime) || Math.abs(now - requestTime) > 30000) {
    res.writeHead(401);
    res.end('Token expired');
    return;
  }

  if (!verifyServiceToken(authHeader, timestampHeader)) {
    res.writeHead(403);
    res.end('Forbidden');
    return;
  }

  const requestId = generateRequestId();
  const ctx: ProcessingContext = {
    requestId,
    bufferKey: `buf-${requestId}`,
    authenticated: true,
    stage: 'init'
  };

  await handleFileUpload(ctx, req, res);
});

server.listen(3000, () => {
  console.log('File processing service running on port 3000');
});
